function getFeaturesForTier(tier: 'premium' | 'enterprise'): string[] {
  const baseFeatures = ['unlimited_todos', 'priority_support', 'custom_themes'];
  const enterpriseFeatures = ['api_access', 'team_collaboration'];
  return tier === 'premium' ? baseFeatures : [...baseFeatures, ...enterpriseFeatures];
}

function calculateSubscriptionEndDate(durationYears = 1): Date {
  const endDate = new Date();
  endDate.setFullYear(endDate.getFullYear() + durationYears);
  return endDate;
}

